680	func returnFlowCalls(block string, params map[string]bool) []returnFlowCall {
681		stripped := stripCodeLiteralsAndComments(block)
682		flows := map[string]returnFlowCall{}
683		for _, name := range returnFlowCallNames(block) {
684			flows[name+"\x00return_flow"] = returnFlowCall{
685				Name:         name,
686				Reason:       "callee return value flows into caller return value",
687				EvidenceKind: "return_flow",
688				Detail:       name,
689				Direction:    "callee_to_caller",
690			}
691		}
692		for _, flow := range ternaryReturnFlows(stripped) {
693			flows[flow.Name+"\x00"+flow.EvidenceKind] = flow
694		}
695		for _, flow := range fallbackReturnFlows(stripped) {
696			flows[flow.Name+"\x00"+flow.EvidenceKind] = flow
697		}
698		for _, flow := range expressionAssignedReturnFlows(stripped) {
699			flows[flow.Name+"\x00"+flow.EvidenceKind+"\x00"+flow.Detail] = flow
700		}
701		assigned := map[string]string{}
702		for _, match := range assignCallRe.FindAllStringSubmatchIndex(stripped, -1) {
703			if len(match) != 6 {
704				continue
705			}
706			if isExpressionAssignmentLine(stripped, match[0]) {
707				continue
708			}
709			varName := strings.TrimPrefix(stripped[match[2]:match[3]], "$")
710			callee := strings.TrimPrefix(stripped[match[4]:match[5]], "$")
711			if varName != "" && callee != "" {
712				assigned[varName] = callee
713			}
714		}
715		for _, match := range returnVarRe.FindAllStringSubmatchIndex(stripped, -1) {
716			if len(match) != 4 {
717				continue
718			}
719			if followsReturnedVariable(stripped, match[1]) {
720				continue
721			}
722			varName := strings.TrimPrefix(stripped[match[2]:match[3]], "$")
723			name := assigned[varName]
724			if name == "" {
725				continue
726			}
727			flows[name+"\x00assigned_return_flow"] = returnFlowCall{
728				Name:         name,
729				Reason:       "callee return value assigned to local and returned by caller",
730				EvidenceKind: "assigned_return_flow",
731				Detail:       name + " -> " + varName,
732				Direction:    "callee_to_caller",
733			}
734		}
735		for _, match := range returnPropertyRe.FindAllStringSubmatchIndex(stripped, -1) {
736			if len(match) != 6 {
737				continue
738			}
739			if followsReturnedVariable(stripped, match[1]) {
740				continue
741			}
742			varName := strings.TrimPrefix(stripped[match[2]:match[3]], "$")
743			property := strings.TrimPrefix(stripped[match[4]:match[5]], "$")
744			name := assigned[varName]
745			if name == "" || property == "" {
746				continue
747			}
748			flows[name+"\x00assigned_property_return_flow"] = returnFlowCall{
749				Name:         name,
750				Reason:       "callee return value assigned to local and returned through property by caller",
751				EvidenceKind: "assigned_property_return_flow",
752				Detail:       name + " -> " + varName + "." + property,
753				Direction:    "callee_to_caller",
754			}
755		}
756		for _, flow := range branchAssignedReturnFlows(stripped) {
757			flows[flow.Name+"\x00assigned_return_flow"] = flow
758		}
759		for _, flow := range argumentForwardingFlows(stripped, params) {
760			flows[flow.Name+"\x00"+flow.EvidenceKind+"\x00"+flow.Detail] = flow
761		}
762		for _, flow := range parameterPropertyForwardingFlows(stripped, params) {
763			flows[flow.Name+"\x00"+flow.EvidenceKind+"\x00"+flow.Detail] = flow
764		}
765		for _, flow := range parameterPropertyAliasForwardingFlows(stripped, params) {
